const QUESTION_SOURCE_B64 = "";

const EXTRA_QUESTIONS = [
  // Exemplu pentru adăugări viitoare:
  // {
  //   category: "HTML",
  //   title: "Titlul întrebării",
  //   prompt: "Textul întrebării",
  //   codeSnippets: ["<form action=\"save.php\" method=\"post\"></form>"],
  //   options: [
  //     { text: "Varianta A", correct: false },
  //     { text: "Varianta B", correct: true }
  //   ]
  // }
];

const CATEGORY_ORDER = [
  "HTML",
  "CSS",
  "JavaScript",
  "PHP",
  "Laravel",
  "Testarea",
  "Administrare server",
  "Management"
];

const STORAGE_KEY = "webby-examen-recap-v1";

const app = {
  questions: [],
  questionsById: new Map(),
  state: null,
  search: "",
  revealedAnswers: new Set(),
  validationMessage: "",
  roundNotice: ""
};

document.addEventListener("DOMContentLoaded", init);

function init() {
  const source = decodeQuestionSource(QUESTION_SOURCE_B64);
  app.questions = parseQuestionSource(source).concat(normalizeExtraQuestions(EXTRA_QUESTIONS));
  assignCategoryIndexes(app.questions);
  app.questionsById = new Map(app.questions.map((question) => [question.id, question]));
  app.state = loadState();

  document.getElementById("resetProgress").addEventListener("click", () => {
    if (window.confirm("Resetezi progresul testului?")) {
      resetProgress();
    }
  });

  document.getElementById("questionSearch").addEventListener("input", (event) => {
    app.search = event.target.value.trim();
    renderNavigation();
  });

  document.getElementById("categoryList").addEventListener("click", (event) => {
    const button = event.target.closest("[data-question-id]");
    if (!button) return;
    goToQuestion(button.dataset.questionId);
  });

  document.getElementById("questionCard").addEventListener("click", handleQuestionAction);

  const card = document.getElementById("questionCard");
  card.addEventListener("dragstart", handleMatchDragStart);
  card.addEventListener("dragover", handleMatchDragOver);
  card.addEventListener("drop", handleMatchDrop);
  card.addEventListener("dragend", handleMatchDragEnd);
  card.addEventListener("touchstart", handleMatchTouchStart, { passive: false });
  card.addEventListener("touchmove", handleMatchTouchMove, { passive: false });
  card.addEventListener("touchend", handleMatchTouchEnd);

  render();
}

let matchDragState = null;

function handleMatchDragStart(event) {
  const chip = event.target.closest(".match-chip");
  const filledDrop = event.target.closest(".match-drop.filled, .blank-drop-inline.filled");
  if (chip) {
    matchDragState = { value: chip.dataset.matchValue, source: "pool" };
    chip.classList.add("dragging");
    event.dataTransfer.effectAllowed = "move";
  } else if (filledDrop) {
    matchDragState = { value: filledDrop.dataset.matchValue, source: "drop", sourceEl: filledDrop };
    event.dataTransfer.effectAllowed = "move";
  }
}

function handleMatchDragOver(event) {
  const drop = event.target.closest(".match-drop:not(.correct):not(.incorrect), .blank-drop-inline:not(.correct):not(.incorrect)");
  if (drop && matchDragState) {
    event.preventDefault();
    drop.classList.add("drag-over");
  }
}

function handleMatchDrop(event) {
  event.preventDefault();
  const drop = event.target.closest(".match-drop, .blank-drop-inline");
  if (!drop || !matchDragState) return;
  drop.classList.remove("drag-over");

  if (matchDragState.source === "drop" && matchDragState.sourceEl) {
    const oldValue = drop.dataset.matchValue;
    matchDragState.sourceEl.dataset.matchValue = oldValue || "";
    matchDragState.sourceEl.innerHTML = oldValue ? renderInline(oldValue) : "";
    matchDragState.sourceEl.classList.toggle("filled", !!oldValue);
  } else {
    const oldValue = drop.dataset.matchValue;
    if (oldValue) {
      const pool = document.getElementById("matchPool");
      if (pool) {
        const chip = document.createElement("div");
        chip.className = "match-chip";
        chip.draggable = true;
        chip.dataset.matchValue = oldValue;
        chip.innerHTML = renderInline(oldValue);
        pool.appendChild(chip);
      }
    }
  }

  drop.dataset.matchValue = matchDragState.value;
  drop.innerHTML = escapeHtml(matchDragState.value);
  drop.classList.add("filled");
  if (drop.classList.contains("blank-drop-inline")) drop.draggable = true;

  const pool = document.getElementById("matchPool");
  if (pool && matchDragState.source === "pool") {
    const chips = pool.querySelectorAll(".match-chip");
    chips.forEach(c => { if (c.dataset.matchValue === matchDragState.value) { c.remove(); return; } });
  }

  matchDragState = null;
}

function handleMatchDragEnd() {
  document.querySelectorAll(".match-chip.dragging").forEach(el => el.classList.remove("dragging"));
  document.querySelectorAll(".match-drop.drag-over, .blank-drop-inline.drag-over").forEach(el => el.classList.remove("drag-over"));
  matchDragState = null;
}

let touchDragEl = null;
let touchDragClone = null;
let touchDragValue = null;
let touchDragSource = null;

function handleMatchTouchStart(event) {
  const chip = event.target.closest(".match-chip");
  const filledDrop = event.target.closest(".match-drop.filled, .blank-drop-inline.filled");
  const target = chip || filledDrop;
  if (!target) return;

  event.preventDefault();
  touchDragEl = target;
  touchDragValue = target.dataset.matchValue;
  touchDragSource = chip ? "pool" : "drop";

  touchDragClone = target.cloneNode(true);
  touchDragClone.style.cssText = "position:fixed;z-index:9999;pointer-events:none;opacity:0.85;width:" + target.offsetWidth + "px;";
  document.body.appendChild(touchDragClone);

  const touch = event.touches[0];
  touchDragClone.style.left = (touch.clientX - target.offsetWidth / 2) + "px";
  touchDragClone.style.top = (touch.clientY - 20) + "px";
  target.style.opacity = "0.3";
}

function handleMatchTouchMove(event) {
  if (!touchDragClone) return;
  event.preventDefault();
  const touch = event.touches[0];
  touchDragClone.style.left = (touch.clientX - touchDragClone.offsetWidth / 2) + "px";
  touchDragClone.style.top = (touch.clientY - 20) + "px";

  document.querySelectorAll(".match-drop.drag-over, .blank-drop-inline.drag-over").forEach(el => el.classList.remove("drag-over"));
  const elementBelow = document.elementFromPoint(touch.clientX, touch.clientY);
  if (elementBelow) {
    const drop = elementBelow.closest(".match-drop, .blank-drop-inline");
    if (drop) drop.classList.add("drag-over");
  }
}

function handleMatchTouchEnd(event) {
  if (!touchDragClone) return;

  const touch = event.changedTouches[0];
  if (touchDragClone.parentNode) touchDragClone.remove();

  const elementBelow = document.elementFromPoint(touch.clientX, touch.clientY);
  const drop = elementBelow ? elementBelow.closest(".match-drop, .blank-drop-inline") : null;
  drop && drop.classList.remove("drag-over");

  if (drop && touchDragValue) {
    if (touchDragSource === "drop" && touchDragEl) {
      const oldValue = drop.dataset.matchValue;
      touchDragEl.dataset.matchValue = oldValue || "";
      touchDragEl.innerHTML = oldValue ? renderInline(oldValue) : "";
      touchDragEl.classList.toggle("filled", !!oldValue);
      touchDragEl.style.opacity = "";
    } else {
      const oldValue = drop.dataset.matchValue;
      if (oldValue) {
        const pool = document.getElementById("matchPool");
        if (pool) {
          const chip = document.createElement("div");
          chip.className = "match-chip";
          chip.draggable = true;
          chip.dataset.matchValue = oldValue;
          chip.innerHTML = renderInline(oldValue);
          pool.appendChild(chip);
        }
      }
      if (touchDragEl) touchDragEl.remove();
    }

    drop.dataset.matchValue = touchDragValue;
    drop.innerHTML = renderInline(touchDragValue);
    drop.classList.add("filled");
  } else if (touchDragEl) {
    touchDragEl.style.opacity = "";
  }

  touchDragEl = null;
  touchDragClone = null;
  touchDragValue = null;
  touchDragSource = null;
}

function decodeQuestionSource(encoded) {
  if (!encoded || encoded === "__QUESTION_SOURCE_B64__") {
    return "";
  }

  const bytes = Uint8Array.from(atob(encoded), (char) => char.charCodeAt(0));
  return new TextDecoder("utf-8").decode(bytes);
}

function parseQuestionSource(source) {
  if (!source.trim()) return [];

  const chunks = source
    .replace(/\r\n/g, "\n")
    .split(/\n(?=##\s+)/)
    .filter((chunk) => chunk.trim().startsWith("## "));

  return chunks.map((chunk, index) => {
    const lines = chunk.split("\n");
    const title = lines.shift().replace(/^##\s+/, "").trim();
    const promptLines = [];
    const optionRows = [];
    const answerRows = [];

    const poolItems = [];

    for (const rawLine of lines) {
      const line = rawLine.trim();
      if (!line || line === "---") continue;

      const optionMatch = line.match(/^-\s+(.*)$/);
      if (!optionMatch) {
        promptLines.push(line);
        continue;
      }

      const value = optionMatch[1].trim();

      const poolMatch = value.match(/^_pool_:\s*(.+)$/);
      if (poolMatch) {
        const poolVal = poolMatch[1].replace(/`/g, "").trim();
        if (poolVal) poolItems.push(poolVal);
        continue;
      }

      if (isAnswerLine(value)) {
        answerRows.push(cleanAnswerLine(value));
        continue;
      }

      optionRows.push({
        text: cleanOptionText(value),
        correct: hasCorrectMarker(value)
      });
    }

    const rawPrompt = promptLines.join("\n").trim();
    const display = buildQuestionDisplay(title, rawPrompt);
    const prompt = display.prompt;
    const correspondence = isReferenceAnswer(title, prompt, optionRows);
    const hasMarkedOptions = optionRows.some((option) => option.correct);
    let options = [];
    let answer = "";
    let answerMode = "options";

    let matchPairs = [];
    if (correspondence && optionRows.length) {
      matchPairs = extractMatchPairs(optionRows);
    }

    const hasBlankFill = /___/.test(rawPrompt) || /___/.test(title);
    let blankAnswers = [];

    if (hasBlankFill) {
      const answerSource = answerRows.length ? answerRows.join("\n") : optionRows.filter(o => o.correct).map(o => o.text).join(", ");
      blankAnswers = extractBlankAnswers(answerSource, rawPrompt + "\n" + title);
    }

    if (hasBlankFill && blankAnswers.length && poolItems.length) {
      answerMode = "drag-blanks";
      answer = answerRows.length ? answerRows.join("\n") : optionRows.map(o => o.text).join("\n");
    } else if (hasBlankFill && blankAnswers.length) {
      answerMode = "blanks";
      answer = answerRows.length ? answerRows.join("\n") : optionRows.map(o => o.text).join("\n");
    } else if (optionRows.length && hasMarkedOptions && !correspondence) {
      options = optionRows.map((option, optionIndex) => ({
        id: `o${optionIndex + 1}`,
        text: option.text,
        correct: option.correct
      }));
    } else if (matchPairs.length) {
      answerMode = "match";
      answer = matchPairs.map(p => `${p.term} → ${p.definition}`).join("\n");
    } else {
      answerMode = "self";
      answer = answerRows.length
        ? answerRows.join("\n")
        : optionRows.map((option) => option.text).join("\n");
    }

    const base = `${title}\n${prompt}\n${optionRows.map((option) => option.text).join("\n")}\n${answer}`;
    const category = detectCategory(title, base);

    return {
      id: `q${index + 1}`,
      sourceIndex: index + 1,
      category,
      categoryIndex: 0,
      title,
      prompt,
      options,
      answer,
      answerMode,
      matchPairs,
      blankAnswers,
      blankPool: poolItems,
      codeSnippets: display.codeSnippets
    };
  });
}

function normalizeExtraQuestions(extraQuestions) {
  return extraQuestions.map((item, index) => {
    const options = Array.isArray(item.options)
      ? item.options.map((option, optionIndex) => {
          if (typeof option === "string") {
            return { id: `o${optionIndex + 1}`, text: option, correct: false };
          }
          return {
            id: `o${optionIndex + 1}`,
            text: option.text || "",
            correct: Boolean(option.correct)
          };
        })
      : [];

    const rawPrompt = item.prompt || "";
    const display = buildQuestionDisplay(item.title || "", rawPrompt);
    const prompt = display.prompt;
    return {
      id: `extra-${index + 1}`,
      sourceIndex: 10000 + index,
      category: CATEGORY_ORDER.includes(item.category) ? item.category : detectCategory(item.title || "", prompt),
      categoryIndex: 0,
      title: item.title || `Întrebare nouă ${index + 1}`,
      prompt,
      options,
      answer: item.answer || "",
      answerMode: options.length ? "options" : "self",
      matchPairs: item.matchPairs || [],
      codeSnippets: item.codeSnippets || display.codeSnippets
    };
  });
}

function assignCategoryIndexes(questions) {
  const counters = Object.fromEntries(CATEGORY_ORDER.map((category) => [category, 0]));
  for (const question of questions) {
    counters[question.category] = (counters[question.category] || 0) + 1;
    question.categoryIndex = counters[question.category];
  }
}

function isAnswerLine(value) {
  const plain = stripMarkdown(value);
  return /^Răspuns\b/i.test(plain) || /^Raspuns\b/i.test(normalizePlain(plain));
}

function cleanAnswerLine(value) {
  return value
    .replace(/\s*—\s*true\b.*$/i, "")
    .replace(/^\*\*Răspuns(?:\s*\([^)]*\))?\s*:\s*/i, "")
    .replace(/^\*\*Raspuns(?:\s*\([^)]*\))?\s*:\s*/i, "")
    .replace(/^\*\*Răspuns(?:\s*\([^)]*\))?\s*/i, "")
    .replace(/^\*\*Raspuns(?:\s*\([^)]*\))?\s*/i, "")
    .replace(/\*\*$/g, "")
    .trim();
}

function hasCorrectMarker(value) {
  return /\s—\s*true\b/i.test(value);
}

function cleanOptionText(value) {
  return value
    .replace(/\s*—\s*true\b.*$/i, "")
    .trim();
}

function isReferenceAnswer(title, prompt, optionRows) {
  const combined = normalizePlain(`${title}\n${prompt}\n${optionRows.map((option) => option.text).join("\n")}`);
  const arrowCount = optionRows.filter((option) => option.text.includes("→")).length;
  return (
    combined.includes("corespondenta") ||
    combined.includes("coresponden") ||
    title.includes("↔") ||
    arrowCount >= 2
  );
}

function extractBlankAnswers(answerText, promptText) {
  const blankCount = (promptText.match(/___/g) || []).length;
  if (!blankCount) return [];

  const codeTokens = Array.from(answerText.matchAll(/`([^`]+)`/g)).map(m => m[1].trim());
  if (codeTokens.length >= blankCount) return codeTokens.slice(0, blankCount);

  const cleaned = answerText.replace(/\*\*/g, "").replace(/`/g, "");
  const tokens = cleaned
    .split(/[,;/\n]/)
    .map(t => t.replace(/^\s*\(.*?\)\s*$/, "").trim())
    .filter(t => t.length > 0 && t.length < 60);
  return tokens.slice(0, blankCount);
}

function extractMatchPairs(optionRows) {
  const pairs = [];
  for (const row of optionRows) {
    const text = row.text;
    const arrowMatch = text.match(/^(.+?)\s*[→↔]\s*(.+)$/);
    if (arrowMatch) {
      pairs.push({
        term: arrowMatch[1].trim(),
        definition: arrowMatch[2].trim()
      });
    }
  }
  return pairs;
}

function detectCategory(title, fullText) {
  const numbered = title.match(/^Întrebarea\s+(\d+)/i);
  if (numbered) {
    const number = Number(numbered[1]);
    if (number >= 1 && number <= 4) return "HTML";
    if (number >= 5 && number <= 8) return "CSS";
    if (number >= 9 && number <= 13) return "JavaScript";
    if (number >= 14 && number <= 20) return "PHP";
    if (number >= 21 && number <= 26) return "Laravel";
    if (number >= 27 && number <= 33) return "Testarea";
    if (number >= 34 && number <= 36) return "Administrare server";
    if (number >= 37 && number <= 40) return "Management";
  }

  const text = normalizePlain(`${title}\n${fullText}`);
  const scores = Object.fromEntries(CATEGORY_ORDER.map((category) => [category, 0]));

  addScore(scores, "Laravel", text, [
    /laravel/,
    /blade/,
    /@foreach|@forelse|@empty|@end/,
    /artisan/,
    /controller/,
    /middleware/,
    /\broute\b/,
    /view::/,
    /db::/,
    /auth::/,
    /\brequest\b/,
    /eloquent/,
    /\bmodel\b/,
    /\bmigration\b/,
    /\bseeder\b/,
    /\bcomponent\b/,
    /bookcontroller|usercontroller|calitate::/
  ], 3);

  addScore(scores, "Administrare server", text, [
    /apache/,
    /nginx/,
    /\bmysql\b/,
    /\blamp\b|\bwamp\b/,
    /ssl|tls/,
    /\bdns\b/,
    /wordpress/,
    /ubuntu/,
    /\bapt\b/,
    /grant all/,
    /\.htaccess/,
    /nginx\.conf/,
    /web server|iis|xampp|phpmyadmin/
  ], 3);

  addScore(scores, "Management", text, [
    /\bgit\b/,
    /repozitoriu/,
    /commit/,
    /branch|ramur/,
    /control al versiunilor/,
    /project manager|team leader|client|software developer/,
    /ciclu de viata/,
    /spiral|waterfall|agile|modelul v|code-and-fix|big-bang/
  ], 3);

  addScore(scores, "Testarea", text, [
    /testare/,
    /\bbug\b/,
    /prototip/,
    /calit/,
    /white box|black box|grey box/,
    /cazuri? de test/,
    /planul de testare/,
    /specifica/,
    /validare_html/,
    /graf/,
    /performan/,
    /vulnerabilit/,
    /erori/,
    /programatorul testeaz/
  ], 3);

  addScore(scores, "JavaScript", text, [
    /javascript|\bjs\b/,
    /console\.log/,
    /document\./,
    /\bvar\s/,
    /\barray\b/,
    /math\./,
    /slice/,
    /setinterval/,
    /typeof/,
    /addeventlistener/,
    /prompt|confirm|alert/,
    /onmouse/,
    /getfullyear/,
    /tofixed/,
    /reverse|join/,
    /search\(/,
    /number\(/,
    /\+\+a/,
    /swap/,
    /test\(5,\s*"6"\)/,
    /conversie string/
  ], 2);

  addScore(scores, "PHP", text, [
    /\bphp\b/,
    /\$_/,
    /\$[a-z_]/,
    /mysqli/,
    /fopen/,
    /session/,
    /echo/,
    /foreach/,
    /explode/,
    /die\(\)|exit\(\)/,
    /global/,
    /\?\?/,
    /define/,
    /print_r/,
    /composer/,
    /operator egalitate/,
    /declarare constanta/,
    /incrementare count/,
    /interpretator/
  ], 2);

  addScore(scores, "CSS", text, [
    /\bcss\b/,
    /selector/,
    /\bstyle\b/,
    /foaie de stil/,
    /border/,
    /padding/,
    /margin/,
    /color/,
    /background/,
    /\bfont\b/,
    /position/,
    /z-index/,
    /\bclass\b/,
    /#zag/,
    /span/,
    /fundal/,
    /chenar/,
    /italic/,
    /pseudoclas/,
    /nume corecte de clase/,
    /extensia fisierului css/
  ], 2);

  addScore(scores, "HTML", text, [
    /\bhtml\b/,
    /marcaj/,
    /formular/,
    /<form|<input|<select|<option|<img|<a\b|<meta|<td|<title/,
    /browser/,
    /pagina web|site web/,
    /\bhttp\b/,
    /\blink\b/,
    /liste/,
    /tabel/,
    /buton cu imagine/,
    /atributul action/,
    /camp de editare/,
    /documentului html/,
    /elemente de structura/
  ], 2);

  const best = Object.entries(scores).sort((a, b) => b[1] - a[1])[0];
  return best && best[1] > 0 ? best[0] : "HTML";
}

function addScore(scores, category, text, patterns, weight) {
  for (const pattern of patterns) {
    if (pattern.test(text)) {
      scores[category] += weight;
    }
  }
}

function buildQuestionDisplay(title, prompt) {
  const source = `${title}\n${prompt}`;
  const codeSnippets = extractCodeSnippets(source);
  const specialDisplay = getSpecialQuestionDisplay(title, prompt);
  if (specialDisplay) {
    return specialDisplay;
  }

  const bareTitleCode = extractBareTitleCode(title, prompt, codeSnippets);
  if (bareTitleCode) {
    codeSnippets.unshift(bareTitleCode);
  }

  return {
    prompt: buildConditionText(title, cleanPromptCodeReferences(prompt, codeSnippets), bareTitleCode),
    codeSnippets
  };
}

function extractCodeSnippets(source) {
  const snippets = [];
  for (const match of source.matchAll(/`([^`]+)`/g)) {
    const snippet = match[1].trim();
    if (!snippet || !looksLikeCode(snippet)) continue;
    if (isStandaloneTagReference(snippet)) continue;

    const repeatCount = getInlineCodeRepeatCount(source, match.index);
    snippets.push(Array.from({ length: repeatCount }, () => formatCodeSnippet(snippet)).join("\n"));
  }
  return snippets.slice(0, 8);
}

function looksLikeCode(value) {
  return /[<>{};$()[\]=]|::|console|function|var\s|sudo|git|mysql|php artisan|@foreach|@forelse/.test(value);
}

function isStandaloneTagReference(value) {
  return /^<\/?[a-z][a-z0-9-]*>$/i.test(value.trim());
}

function formatCodeSnippet(value) {
  const trimmed = value.trim();

  if (trimmed.includes("\n") && trimmed.split("\n").length > 2) {
    return trimmed;
  }

  if (/^<style>/i.test(trimmed)) {
    return trimmed.replace(/^<style>\s*(.*?)\s*$/i, "<style>\n  $1\n</style>");
  }

  if (looksLikeCssRule(trimmed)) {
    return trimmed
      .replace(/([a-z0-9.#]+)\+([a-z0-9.#]+)/gi, "$1 + $2")
      .replace(/\{\s*/g, "{ ")
      .replace(/\s*\}/g, " }")
      .replace(/;\s*/g, ";\n  ")
      .replace(/\{\s+([^{}\n]+)\s+\}/g, (_, body) => `{\n  ${body.trim()}\n}`)
      .replace(/\n\s+\}/g, "\n}")
      .trim();
  }

  if (looksLikeImperativeCode(trimmed)) {
    return formatImperativeCode(trimmed);
  }

  return trimmed;
}

function looksLikeImperativeCode(value) {
  return /\b(function|var |let |const |for\s*\(|while\s*\(|if\s*\(|else|console\.|document\.|echo |return |\$[a-z_]|<\?php)/i.test(value)
    && value.length > 40
    && !value.includes("\n");
}

function formatImperativeCode(code) {
  let result = code;

  const preserved = [];
  result = result.replace(/\(([^()]*;[^()]*)\)/g, (match) => {
    preserved.push(match);
    return `__PAREN_${preserved.length - 1}__`;
  });

  result = result.replace(/;\s*(?=[^\s"'\)])/g, ";\n");
  result = result.replace(/\{\s*/g, " {\n");
  result = result.replace(/\s*\}/g, "\n}");
  result = result.replace(/\}\s*(?=[a-zA-Z$_@<])/g, "}\n");

  for (let i = 0; i < preserved.length; i++) {
    result = result.replace(`__PAREN_${i}__`, preserved[i]);
  }

  const lines = result.split("\n").map(l => l.trim()).filter(Boolean);
  let indent = 0;
  const formatted = [];

  for (const line of lines) {
    if (/^\}/.test(line) && indent > 0) indent--;
    formatted.push("  ".repeat(indent) + line);
    if (/\{\s*$/.test(line)) indent++;
  }

  return formatted.join("\n");
}

function looksLikeCssRule(value) {
  return /^[.#]?[a-z][a-z0-9\s+.#>~:-]*\{[^{}]+\}$/i.test(value) && !/\b(function|for|if|while|switch|try|catch|return)\b/i.test(value);
}

function getSpecialQuestionDisplay(title, prompt) {
  if (title === "Întrebarea 5") {
    return {
      prompt: "Se dă regula CSS de mai jos. Determinați lățimea totală a elementului <div>.",
      codeSnippets: ["div {\n  width: 250px;\n  padding: 10px;\n  border: 5px solid gray;\n  margin: 10px;\n}"]
    };
  }

  if (title === "Întrebarea 6") {
    return {
      prompt: "În ce caz se aplică stilul CSS definit de selectorul de mai jos?",
      codeSnippets: ["div + p {\n  color: red;\n}"]
    };
  }

  if (title === "Întrebarea 7") {
    return {
      prompt: "Se dau stilurile CSS de mai jos. Determinați înălțimea finală aplicată elementului <div>.",
      codeSnippets: [
        "/* style.css */\ndiv {\n  height: 20px;\n}\n\n<!-- HTML: link extern către style.css -->\n<style>\n  div { height: 10px !important; }\n</style>\n<div style=\"height:15px;\">TEXT 1</div>"
      ]
    };
  }

  if (title === "Întrebarea 8") {
    return {
      prompt: "Care este codul HTML corect pentru conectarea unei foi de stil externe?",
      codeSnippets: []
    };
  }

  return null;
}

function extractBareTitleCode(title, prompt, existingSnippets) {
  if (prompt.trim() || existingSnippets.length || isGenericQuestionTitle(title)) {
    return "";
  }

  const cleanedTitle = title.replace(/\s*\(rep\.\)\s*/i, "").trim();
  if (/^(console\.log|document\.write|alert|try\s*\{|var\s|a=|Math\.)/i.test(cleanedTitle)) {
    return formatCodeSnippet(cleanedTitle);
  }

  return "";
}

function buildConditionText(title, prompt, movedTitleCode) {
  const cleanedPrompt = prompt.trim();
  if (cleanedPrompt) {
    return cleanedPrompt;
  }

  if (movedTitleCode) {
    if (/math\.log/i.test(movedTitleCode)) {
      return "Pentru ce valoare a lui x expresia de mai jos returnează 1?";
    }

    return "Ce va afișa următorul cod?";
  }

  if (!isGenericQuestionTitle(title)) {
    return title.trim();
  }

  return "Selectați răspunsul corect.";
}

function isGenericQuestionTitle(title) {
  return /^Întrebarea\s+\d+\b/i.test(title.trim());
}

function getInlineCodeRepeatCount(source, matchIndex) {
  const before = normalizePlain(source.slice(Math.max(0, matchIndex - 40), matchIndex));

  if (/(^|[ (])(?:trei|3)$/.test(before)) return 3;
  if (/(^|[ (])(?:doua|doi|2)$/.test(before)) return 2;
  if (/(^|[ (])(?:patru|4)$/.test(before)) return 4;
  if (/(^|[ (])(?:cinci|5)$/.test(before)) return 5;

  return 1;
}

function cleanPromptCodeReferences(prompt, codeSnippets) {
  if (!prompt || !codeSnippets.length) {
    return prompt;
  }

  const promptWithoutCode = prompt.replace(/`([^`]+)`/g, (_, snippet) => {
    return shouldRemoveInlineCode(snippet) ? "" : snippet;
  }).trim();
  const codeOnlyPrompt = !promptWithoutCode;

  if (!codeOnlyPrompt && !shouldMoveInlineCodeToBox(prompt)) {
    return prompt;
  }

  if (codeOnlyPrompt) {
    return "Ce va afișa următorul cod?";
  }

  const cleaned = prompt
    .replace(/`([^`]+)`/g, (full, snippet) => shouldRemoveInlineCode(snippet) ? "" : full)
    .replace(/\((?:un|una|doi|două|doua|trei|patru|cinci|\d+)?\s*\)\s*:?\s*/gi, " ")
    .replace(/\s*\+\s*\+\s*/g, " ")
    .replace(/\s+\./g, ".")
    .replace(/\s+\?/g, "?")
    .replace(/\s+:/g, ":")
    .replace(/cod\s*:$/i, "cod?")
    .replace(/codului\s*:$/i, "codului?")
    .replace(/secvență de cod\s*:$/i, "secvență de cod?")
    .replace(/secventa de cod\s*:$/i, "secvență de cod?")
    .replace(/\s+/g, " ")
    .trim();

  if (/^(ce|care|cum|unde|în ce|in ce)\b/i.test(cleaned) && !/[?.!]$/.test(cleaned)) {
    return `${cleaned}?`;
  }

  return cleaned;
}

function shouldRemoveInlineCode(snippet) {
  return looksLikeCode(snippet) && !isStandaloneTagReference(snippet);
}

function shouldMoveInlineCodeToBox(prompt) {
  return /cod|secvență|secventa|fragment|afișa|afisa|afișează|afiseaza|următoarea|urmatoarea|fie dat|selector|formular|completați|completează|completati|completeaza/i.test(prompt);
}

function loadState() {
  let saved = {};
  try {
    saved = JSON.parse(localStorage.getItem(STORAGE_KEY)) || {};
  } catch (error) {
    saved = {};
  }

  return sanitizeState(saved);
}

function sanitizeState(saved) {
  const ids = new Set(app.questions.map((question) => question.id));
  const fallbackQueue = app.questions.map((question) => question.id);
  const results = {};
  const roundAnswers = {};

  for (const [id, result] of Object.entries(saved.results || {})) {
    if (ids.has(id)) {
      results[id] = result;
    }
  }

  for (const [id, answer] of Object.entries(saved.roundAnswers || {})) {
    if (ids.has(id) && (answer === "correct" || answer === "wrong")) {
      roundAnswers[id] = answer;
    }
  }

  const queue = Array.isArray(saved.queue)
    ? saved.queue.filter((id) => ids.has(id))
    : fallbackQueue;

  return {
    currentId: ids.has(saved.currentId) ? saved.currentId : fallbackQueue[0],
    queue: queue.length ? queue : fallbackQueue,
    round: Number.isInteger(saved.round) && saved.round > 0 ? saved.round : 1,
    roundAnswers,
    results,
    finished: Boolean(saved.finished)
  };
}

function makeFreshState() {
  return {
    currentId: app.questions[0] ? app.questions[0].id : null,
    queue: app.questions.map((question) => question.id),
    round: 1,
    roundAnswers: {},
    results: {},
    finished: false
  };
}

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(app.state));
}

function resetProgress() {
  app.state = makeFreshState();
  app.revealedAnswers.clear();
  app.roundNotice = "";
  app.questions.forEach(q => { delete q._shuffledOptions; });
  saveState();
  render();
}

function render() {
  renderStatus();
  renderNavigation();
  renderQuestion();
}

function renderStatus() {
  const total = app.questions.length;
  const results = Object.values(app.state.results);
  const correct = results.filter((result) => result.status === "correct").length;
  const wrong = results.filter((result) => result.status === "wrong").length;
  const remaining = app.state.queue.filter((id) => !app.state.roundAnswers[id]).length;

  document.getElementById("statusStrip").innerHTML = [
    metric("Runda", app.state.finished ? "Final" : app.state.round),
    metric("Corecte", `${correct}/${total}`),
    metric("Greșite active", wrong),
    metric("Rămase în rundă", remaining)
  ].join("");
}

function metric(label, value) {
  return `<div class="metric"><span>${escapeHtml(label)}</span><strong>${escapeHtml(String(value))}</strong></div>`;
}

function renderNavigation() {
  const list = document.getElementById("categoryList");
  const query = normalizePlain(app.search);
  const html = CATEGORY_ORDER.map((category) => {
    const questions = app.questions.filter((question) => {
      if (question.category !== category) return false;
      if (!query) return true;
      return normalizePlain(`${question.title}\n${question.prompt}`).includes(query);
    });

    if (!questions.length) return "";

    const buttons = questions.map((question) => {
      const result = app.state.results[question.id];
      const statusClass = result ? result.status : "";
      const active = question.id === app.state.currentId ? " active" : "";
      const queued = app.state.queue.includes(question.id) && !app.state.roundAnswers[question.id] ? " queued" : "";
      return `
        <button
          class="nav-question ${statusClass}${active}${queued}"
          type="button"
          data-question-id="${escapeHtml(question.id)}"
          title="${escapeHtml(question.title)}">
          ${question.categoryIndex}
        </button>
      `;
    }).join("");

    return `
      <section class="category-block">
        <h3 class="category-title">${escapeHtml(category)} <span>${questions.length}</span></h3>
        <div class="question-grid">${buttons}</div>
      </section>
    `;
  }).join("");

  list.innerHTML = html || `<div class="empty-state">Nu am găsit întrebări.</div>`;
}

function renderQuestion() {
  const card = document.getElementById("questionCard");
  app.validationMessage = "";

  if (!app.questions.length) {
    card.innerHTML = `<div class="empty-state">Nu există întrebări în sursa de date.</div>`;
    return;
  }

  if (app.state.finished) {
    const totalAttempts = Object.values(app.state.results).reduce((sum, result) => sum + (result.attempts || 0), 0);
    card.innerHTML = `
      <div class="finish-panel">
        <p class="eyebrow">Final</p>
        <h2>100% rezolvat</h2>
        <p>Toate întrebările din ultima rundă au fost rezolvate corect. Încercări totale: <strong>${totalAttempts}</strong>.</p>
        <div class="actions">
          <button class="primary-button" type="button" data-action="restart">Reia testul</button>
          <button class="secondary-button" type="button" data-action="review-first">Revizuiește întrebările</button>
        </div>
      </div>
    `;
    return;
  }

  const question = app.questionsById.get(app.state.currentId) || app.questions[0];
  const inCurrentQueue = app.state.queue.includes(question.id);
  const locked = inCurrentQueue && Boolean(app.state.roundAnswers[question.id]);
  const result = locked ? app.state.results[question.id] : null;
  const isBlanks = (question.answerMode === "blanks" || question.answerMode === "drag-blanks") && question.blankAnswers && question.blankAnswers.length > 0;
  const isDragBlanks = question.answerMode === "drag-blanks";

  let promptHtml = question.prompt
    ? question.prompt.split("\n").map((line) => `<p>${renderInline(line)}</p>`).join("")
    : "";

  let codeHtml = question.codeSnippets.length ? renderCodeBox(question.codeSnippets) : "";

  if (isBlanks) {
    const blankResults = locked && result ? (result.blankValues || []) : [];
    let blankIndex = 0;

    const replaceBlank = (html) => {
      return html.replace(/___+/g, () => {
        const i = blankIndex++;
        const expected = question.blankAnswers[i] || "";
        if (locked) {
          const userVal = blankResults[i] || "";
          const isOk = normalizePlain(userVal) === normalizePlain(expected);
          if (isDragBlanks) {
            return `<span class="blank-drop-inline ${isOk ? "correct" : "incorrect"}">${escapeHtml(userVal)}</span>` +
              (!isOk ? ` <span class="blank-correct-hint">${escapeHtml(expected)}</span>` : "");
          }
          return `<input class="blank-input ${isOk ? "correct" : "incorrect"}" value="${escapeHtml(userVal)}" disabled>` +
            (!isOk ? ` <span class="blank-correct-hint">${escapeHtml(expected)}</span>` : "");
        }
        if (isDragBlanks) {
          return `<span class="blank-drop-inline" data-blank-index="${i}" data-match-value="">${"..."}</span>`;
        }
        return `<input class="blank-input" data-blank-index="${i}" placeholder="..." autocomplete="off">`;
      });
    };

    const codeHasBlanks = /___/.test(codeHtml);
    const promptHasBlanks = /___/.test(promptHtml);

    if (codeHasBlanks) {
      codeHtml = replaceBlank(codeHtml);
      if (promptHasBlanks) {
        promptHtml = promptHtml.replace(/<code>[^<]*___[^<]*<\/code>/g, "______");
        promptHtml = promptHtml.replace(/___+/g, "______");
      }
    } else {
      promptHtml = replaceBlank(promptHtml);
    }
  }

  const isMatch = question.matchPairs && question.matchPairs.length > 0;
  const answerHtml = isBlanks
    ? renderBlanksActions(question, locked, result)
    : isMatch
      ? renderMatchQuestion(question, locked, result)
      : question.options.length
        ? renderOptionQuestion(question, locked, result)
        : renderTextQuestion(question, locked, result);
  const noticeHtml = app.roundNotice ? `<div class="round-notice">${escapeHtml(app.roundNotice)}</div>` : "";
  app.roundNotice = "";

  card.innerHTML = `
    ${noticeHtml}
    <div class="question-heading">
      <p class="eyebrow">Întrebarea</p>
      <h2 class="question-title">Întrebarea ${question.sourceIndex}</h2>
      <div class="question-meta">
        <span class="pill category">${escapeHtml(question.category)}</span>
        <span class="pill">În ${escapeHtml(question.category)}: #${question.categoryIndex}</span>
      </div>
    </div>
    <section class="question-section">
      <h3 class="section-title">Condiție</h3>
      <div class="prompt">${promptHtml || "<p>Selectați răspunsul corect.</p>"}</div>
    </section>
    ${codeHtml}
    ${answerHtml}
  `;
}

function renderBlanksActions(question, locked, result) {
  const isDrag = question.answerMode === "drag-blanks";
  const action = isDrag ? "submit-drag-blanks" : "submit-blanks";
  const method = isDrag ? "Trageți elementele în spațiile libere." : "Completați fiecare spațiu liber, apoi verificați.";

  let poolHtml = "";
  if (isDrag && !locked && question.blankPool) {
    const allChips = shuffleArray([...question.blankAnswers, ...question.blankPool]);
    poolHtml = `<div class="match-pool" id="matchPool">${allChips.map(val =>
      `<div class="match-chip" draggable="true" data-match-value="${escapeHtml(val)}">${escapeHtml(val)}</div>`
    ).join("")}</div>`;
  }

  return `
    <section class="question-section answer-area">
      <h3 class="section-title">Metoda de răspuns</h3>
      <p class="answer-method">${method}</p>
      ${poolHtml}
      <div class="feedback-placeholder" id="validationMessage"></div>
      ${locked ? renderFeedback(result) : ""}
      <div class="actions">
        ${locked ? "" : `<button class="primary-button" type="button" data-action="${action}">Verifică</button>`}
        <button class="secondary-button" type="button" data-action="next">Următoarea</button>
      </div>
    </section>
  `;
}

function renderCodeBox(snippets) {
  return `
    <div class="code-box">
      <div class="code-box-header">Cod</div>
      <pre>${escapeHtml(snippets.join("\n\n"))}</pre>
    </div>
  `;
}

function getShuffledOptions(question) {
  if (!question._shuffledOptions) {
    question._shuffledOptions = shuffleArray([...question.options]);
  }
  return question._shuffledOptions;
}

function renderOptionQuestion(question, locked, result) {
  const multiple = question.options.filter((option) => option.correct).length > 1;
  const selected = new Set(locked && result ? result.selectedOptionIds || [] : []);
  const method = multiple ? "Alegeți toate variantele corecte." : "Alegeți varianta corectă.";

  const displayOptions = locked ? question.options : getShuffledOptions(question);
  const options = displayOptions.map((option) => {
    const chosen = selected.has(option.id);
    const statusClass = locked && option.correct ? " correct" : locked && chosen && !option.correct ? " incorrect" : "";
    return `
      <li>
        <label class="option-row${statusClass}">
          <input
            type="${multiple ? "checkbox" : "radio"}"
            name="answer-option"
            value="${escapeHtml(option.id)}"
            ${chosen ? "checked" : ""}
            ${locked ? "disabled" : ""}>
          <span class="option-text">${renderInline(option.text)}</span>
        </label>
      </li>
    `;
  }).join("");

  return `
    <section class="question-section answer-area">
      <h3 class="section-title">Metoda de răspuns</h3>
      <p class="answer-method">${method}</p>
      <ul class="option-list">${options}</ul>
      <div class="feedback-placeholder" id="validationMessage"></div>
      ${locked ? renderFeedback(result) : ""}
      <div class="actions">
        ${locked ? "" : `<button class="primary-button" type="button" data-action="submit-options">Verifică</button>`}
        <button class="secondary-button" type="button" data-action="next">Următoarea</button>
      </div>
    </section>
  `;
}

function renderTextQuestion(question, locked, result) {
  const revealed = locked || app.revealedAnswers.has(question.id);
  const expected = question.answer || "Răspunsul este în blocul de repere al întrebării.";
  const canAutoCheck = canAutoCheckAnswer(question);

  return `
    <section class="question-section answer-area">
      <h3 class="section-title">Metoda de răspuns</h3>
      <p class="answer-method">Scrieți răspunsul, apoi verificați-l cu răspunsul corect.</p>
      ${locked ? "" : `<textarea class="text-answer" id="textAnswer" placeholder="Scrie răspunsul"></textarea>`}
      ${revealed ? `<div class="expected-answer"><strong>Răspuns corect</strong>${renderMultiline(expected)}</div>` : ""}
      ${locked ? renderFeedback(result) : ""}
      <div class="actions">
        ${locked ? "" : canAutoCheck ? `<button class="primary-button" type="button" data-action="submit-text">Verifică</button>` : ""}
        ${locked ? "" : `<button class="secondary-button" type="button" data-action="reveal-answer">Arată răspunsul</button>`}
        ${revealed && !locked ? `<button class="primary-button" type="button" data-action="self-correct">Am răspuns corect</button>` : ""}
        ${revealed && !locked ? `<button class="ghost-button" type="button" data-action="self-wrong">Am greșit</button>` : ""}
        <button class="secondary-button" type="button" data-action="next">Următoarea</button>
      </div>
    </section>
  `;
}

function renderMatchQuestion(question, locked, result) {
  const pairs = question.matchPairs;
  const placements = (locked && result) ? (result.placements || {}) : {};

  const pairsHtml = pairs.map((pair, i) => {
    const dropId = `match-drop-${i}`;
    const placedValue = placements[pair.term] || "";
    const isCorrectPlacement = locked && placedValue === pair.definition;
    const isIncorrectPlacement = locked && placedValue && placedValue !== pair.definition;
    const statusClass = isCorrectPlacement ? " correct" : isIncorrectPlacement ? " incorrect" : "";
    const filledClass = placedValue ? " filled" : "";

    return `
      <div class="match-pair">
        <div class="match-term">${renderInline(pair.term)}</div>
        <div class="match-drop${filledClass}${statusClass}" data-drop-index="${i}" data-term="${escapeHtml(pair.term)}" id="${dropId}"
          ${locked ? "" : 'ondragover="event.preventDefault()" ondragleave="this.classList.remove(\'drag-over\')"'}
        >${placedValue ? renderInline(placedValue) : ""}</div>
      </div>
    `;
  }).join("");

  const allDefinitions = pairs.map(p => p.definition);
  const placedSet = new Set(Object.values(placements));
  const poolItems = locked ? [] : shuffleArray([...allDefinitions]).filter(d => !placedSet.has(d));
  const poolHtml = poolItems.map(def => `
    <div class="match-chip" draggable="true" data-match-value="${escapeHtml(def)}">${renderInline(def)}</div>
  `).join("");

  const correctAnswer = locked && result && !locked ? "" : locked ? pairs.map(p =>
    `<strong>${renderInline(p.term)}</strong> → ${renderInline(p.definition)}`
  ).join("<br>") : "";

  return `
    <section class="question-section answer-area">
      <h3 class="section-title">Metoda de răspuns</h3>
      <p class="answer-method">Trageți fiecare definiție lângă termenul corespunzător.</p>
      <div class="match-area" id="matchArea">${pairsHtml}</div>
      ${poolItems.length ? `<div class="match-pool" id="matchPool">${poolHtml}</div>` : ""}
      ${locked && result ? `<div class="expected-answer"><strong>Răspunsuri corecte</strong><br>${correctAnswer}</div>` : ""}
      ${locked ? renderFeedback(result) : ""}
      <div class="actions">
        ${locked ? "" : `<button class="primary-button" type="button" data-action="submit-match">Verifică</button>`}
        <button class="secondary-button" type="button" data-action="next">Următoarea</button>
      </div>
    </section>
  `;
}

function submitBlanksAnswer(question) {
  const isDrag = question.answerMode === "drag-blanks";
  let values;

  if (isDrag) {
    const drops = document.querySelectorAll(".blank-drop-inline");
    values = Array.from(drops).map(el => (el.dataset.matchValue || "").trim());
  } else {
    const inputs = document.querySelectorAll(".blank-input");
    values = Array.from(inputs).map(input => input.value.trim());
  }

  if (values.some(v => !v)) {
    showValidationMessage("Completează toate spațiile libere.");
    return;
  }

  const correct = question.blankAnswers.every((expected, i) =>
    normalizePlain(values[i] || "") === normalizePlain(expected)
  );

  completeQuestion(question.id, correct, { mode: "blanks", blankValues: values });
}

function shuffleArray(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function renderFeedback(result) {
  if (!result) return "";
  const correct = result.status === "correct";
  return `<div class="feedback ${correct ? "correct" : "wrong"}">${correct ? "Corect." : "Greșit. Întrebarea va reveni la finalul rundei."}</div>`;
}

function renderMultiline(text) {
  return text
    .split("\n")
    .filter(Boolean)
    .map((line) => `<p>${renderInline(line)}</p>`)
    .join("");
}

function handleQuestionAction(event) {
  const button = event.target.closest("[data-action]");
  if (!button) return;

  const action = button.dataset.action;
  const question = app.questionsById.get(app.state.currentId);

  if (action === "submit-blanks" || action === "submit-drag-blanks") {
    submitBlanksAnswer(question);
    return;
  }

  if (action === "submit-match") {
    submitMatchAnswer(question);
    return;
  }

  if (action === "submit-options") {
    submitOptionAnswer(question);
    return;
  }

  if (action === "submit-text") {
    submitTextAnswer(question);
    return;
  }

  if (action === "reveal-answer") {
    app.revealedAnswers.add(question.id);
    renderQuestion();
    return;
  }

  if (action === "self-correct") {
    completeQuestion(question.id, true, { mode: "self" });
    return;
  }

  if (action === "self-wrong") {
    completeQuestion(question.id, false, { mode: "self" });
    return;
  }

  if (action === "next") {
    goToNextQueueQuestion();
    return;
  }

  if (action === "restart") {
    resetProgress();
    return;
  }

  if (action === "review-first") {
    goToQuestion(app.questions[0].id);
  }
}

function submitOptionAnswer(question) {
  const checked = Array.from(document.querySelectorAll('input[name="answer-option"]:checked')).map((input) => input.value);
  if (!checked.length) {
    showValidationMessage("Alege cel puțin o variantă.");
    return;
  }

  const correctIds = question.options.filter((option) => option.correct).map((option) => option.id);
  const correct = sameSet(checked, correctIds);
  completeQuestion(question.id, correct, { mode: "options", selectedOptionIds: checked });
}

function submitMatchAnswer(question) {
  const drops = document.querySelectorAll(".match-drop");
  const placements = {};
  let filledCount = 0;
  drops.forEach(drop => {
    const term = drop.dataset.term;
    const value = drop.dataset.matchValue || "";
    if (value) {
      placements[term] = value;
      filledCount++;
    }
  });

  if (filledCount < question.matchPairs.length) {
    showValidationMessage("Completează toate perechile.");
    return;
  }

  const correct = question.matchPairs.every(pair => placements[pair.term] === pair.definition);
  completeQuestion(question.id, correct, { mode: "match", placements });
}

function submitTextAnswer(question) {
  const answer = document.getElementById("textAnswer").value;
  if (!answer.trim()) {
    app.revealedAnswers.add(question.id);
    renderQuestion();
    return;
  }

  if (isTextAnswerCorrect(answer, question.answer)) {
    completeQuestion(question.id, true, { mode: "text", text: answer });
  } else {
    app.revealedAnswers.add(question.id);
    renderQuestion();
  }
}

function completeQuestion(questionId, correct, details) {
  const previous = app.state.results[questionId];
  app.state.results[questionId] = {
    status: correct ? "correct" : "wrong",
    attempts: (previous ? previous.attempts || 0 : 0) + 1,
    updatedAt: new Date().toISOString(),
    ...details
  };

  if (app.state.queue.includes(questionId)) {
    app.state.roundAnswers[questionId] = correct ? "correct" : "wrong";
  }

  app.revealedAnswers.delete(questionId);
  saveState();
  render();
}

function goToQuestion(questionId) {
  if (!app.questionsById.has(questionId)) return;
  app.state.currentId = questionId;
  app.state.finished = false;
  app.revealedAnswers.delete(questionId);
  saveState();
  render();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function goToNextQueueQuestion() {
  const queue = app.state.queue;
  if (!queue.length) {
    finishRound();
    return;
  }

  const currentIndex = Math.max(0, queue.indexOf(app.state.currentId));
  const ordered = queue.slice(currentIndex + 1).concat(queue.slice(0, currentIndex + 1));
  const next = ordered.find((id) => !app.state.roundAnswers[id]);

  if (next) {
    app.state.currentId = next;
    app.revealedAnswers.delete(next);
    saveState();
    render();
    window.scrollTo({ top: 0, behavior: "smooth" });
    return;
  }

  finishRound();
}

function finishRound() {
  const unanswered = app.state.queue.filter((id) => !app.state.roundAnswers[id]);
  if (unanswered.length) {
    app.state.currentId = unanswered[0];
    saveState();
    render();
    return;
  }

  const wrong = app.state.queue.filter((id) => app.state.roundAnswers[id] === "wrong");
  if (wrong.length) {
    app.state.queue = wrong;
    app.state.roundAnswers = {};
    app.state.round += 1;
    app.state.currentId = wrong[0];
    app.state.finished = false;
    app.roundNotice = `Repeti ${wrong.length} întrebări greșite până când toate sunt corecte.`;
  } else {
    app.state.finished = true;
  }

  saveState();
  render();
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function showValidationMessage(message) {
  const target = document.getElementById("validationMessage");
  if (target) {
    target.innerHTML = `<div class="feedback wrong">${escapeHtml(message)}</div>`;
  }
}

function sameSet(left, right) {
  if (left.length !== right.length) return false;
  const leftSet = new Set(left);
  return right.every((item) => leftSet.has(item));
}

function canAutoCheckAnswer(question) {
  const answer = question.answer || "";
  if (!answer.trim()) return false;
  const normalizedTitle = normalizePlain(question.title);
  if (answer.length > 160) return false;
  if (answer.includes("→") || normalizedTitle.includes("corespondenta") || normalizedTitle.includes("ordine")) return false;
  return true;
}

function isTextAnswerCorrect(userAnswer, expectedAnswer) {
  const user = normalizePlain(userAnswer);
  const expected = normalizePlain(expectedAnswer);
  if (!user || !expected) return false;
  if (user === expected || user.includes(expected)) return true;

  const tokens = extractAnswerTokens(expectedAnswer).map(normalizePlain).filter(Boolean);
  return tokens.length > 0 && tokens.every((token) => user.includes(token));
}

function extractAnswerTokens(answer) {
  const codeTokens = Array.from(answer.matchAll(/`([^`]+)`/g)).map((match) => match[1]);
  if (codeTokens.length) return codeTokens;

  return answer
    .replace(/\*\*/g, "")
    .split(/[,;/\n]|(?:\s+și\s+)|(?:\s+sau\s+)/i)
    .map((piece) => piece.trim())
    .filter((piece) => piece.length > 1 && piece.length < 50)
    .slice(0, 8);
}

function renderInline(text) {
  let html = escapeHtml(text);
  html = html.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, `<img src="$2" alt="$1" style="max-width:100%;border-radius:8px;margin:8px 0;display:block">`);
  html = html.replace(/`([^`]+)`/g, "<code>$1</code>");
  html = html.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  return html;
}

function stripMarkdown(text) {
  return text
    .replace(/\*\*/g, "")
    .replace(/`/g, "")
    .trim();
}

function normalizePlain(text) {
  return String(text || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[„”"']/g, "")
    .replace(/\s+/g, " ")
    .toLowerCase()
    .trim();
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}
